(()=>{var t=document.getElementById("enabled"),s=document.getElementById("open-options"),r=document.getElementById("open-shortcuts"),e=document.getElementById("shortcut-hint");function d(){if(!chrome?.storage?.sync){t.checked=!0,e.textContent="";return}chrome.storage.sync.get({enabled:!0},n=>{t.checked=n.enabled!==!1})}function h(){chrome?.storage?.sync&&chrome.storage.sync.set({enabled:t.checked})}function m(){if(!chrome?.commands?.getAll){e.textContent="";return}chrome.commands.getAll(n=>{let o=n.find(c=>c.name==="toggle-extension");o?.shortcut?e.textContent=`Shortcut: ${o.shortcut}`:e.textContent="Shortcut: not set"})}t.addEventListener("change",h);s.addEventListener("click",()=>chrome.runtime.openOptionsPage());r.addEventListener("click",()=>{chrome.tabs.create({url:"chrome://extensions/shortcuts"})});d();m();})();
